import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(n + 1)]
    edges = []

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)
        edges.append((u, v))

    color = [0] * (n + 1)
    possible = True

    for start_node in range(1, n + 1):
        if color[start_node] != 0:
            continue

        stack = [(start_node, 1)]
        while stack:
            u, c = stack.pop()
            if color[u] != 0:
                if color[u] != c:
                    possible = False
                    break
                continue

            color[u] = c
            for v in adj[u]:
                if color[v] == 0:
                    stack.append((v, 3 - c))
                elif color[v] == c:
                    possible = False
                    break
            if not possible:
                break
        if not possible:
            break

    if not possible:
        print("-1")
        return

    set_a = []
    set_b = []

    for i in range(1, n + 1):
        if color[i] == 1:
            set_a.append(i)
        else:
            set_b.append(i)

    for u, v in edges:
        u_in_a = color[u] == 1
        v_in_a = color[v] == 1
        u_in_b = color[u] == 2
        v_in_b = color[v] == 2

        if not (u_in_a or v_in_a):
            print("-1")
            return
        if not (u_in_b or v_in_b):
            print("-1")
            return

    print(len(set_a))
    print(*(set_a))
    print(len(set_b))
    print(*(set_b))

if __name__ == "__main__":
    main()
